public class Solution {
    private static final Set<String> RESERVED_SET;

    static {
        Set<String> words = new HashSet<>();
        Collections.addAll(words,
            "abstract", "assert", "boolean", "break", "byte", "case", "catch", "char",
            "class", "const", "continue", "default", "do", "double", "else", "enum",
            "extends", "final", "finally", "float", "for", "goto", "if", "implements",
            "import", "instanceof", "int", "interface", "long", "native", "new", "package",
            "private", "protected", "public", "return", "short", "static", "strictfp",
            "super", "switch", "synchronized", "this", "throw", "throws", "transient",
            "try", "void", "volatile", "while", "_", "true", "false", "null"
        );
        RESERVED_SET = Collections.unmodifiableSet(words);
    }

    public static String classifyToken(String token) {
        if (token.equals("true") || token.equals("false") || token.equals("null")) {
            return "Reserved Literal (Illegal Identifier)";
        }
        if (RESERVED_SET.contains(token)) {
            return "Reserved Keyword (Illegal Identifier)";
        }
        return "Valid Identifier";
    }

    public static void main(String[] args) {
        String[] tokens = {"class", "null", "recordData", "goto", "validMethod"};
        for (String t : tokens) {
            System.out.println(t + ": " + classifyToken(t));
        }
    }
}

public class Solution {
    public static String classifyConvention(String token) {
        if (token == null || token.isEmpty() || Character.isDigit(token.charAt(0)) || token.contains("-")) {
            return "INVALID_IDENTIFIER";
        }
        if (token.matches("^[A-Z][A-Z0-9_]+$")) {
            return "CONSTANT_CONVENTION (UPPER_SNAKE_CASE)";
        }
        if (Character.isUpperCase(token.charAt(0)) && !token.contains("_")) {
            return "CLASS_CONVENTION (PascalCase)";
        }
        if (Character.isLowerCase(token.charAt(0)) && !token.contains("_")) {
            return "METHOD_OR_VARIABLE_CONVENTION (camelCase)";
        }
        return "LEGAL_BUT_NON_CONVENTIONAL";
    }

    public static void main(String[] args) {
        String[] tokens = {"OrderService", "calculateTax", "MAX_CAPACITY", "2ndPlace", "_internalRef"};
        for (String t : tokens) {
            System.out.println(t + " -> " + classifyConvention(t));
        }
    }
}

