public class Solution {
    private static final Set<String> CONTEXTUAL_KEYWORDS = new HashSet<>(Arrays.asList(
        "var", "yield", "record", "sealed", "permits", "non-sealed", "module", "open", "opens", "to", "with"
    ));

    private static final Set<String> GLOBAL_KEYWORDS = new HashSet<>(Arrays.asList(
        "class", "interface", "public", "static", "void", "int", "for", "while", "return"
    ));

    public static String inspectKeywordType(String token) {
        if (GLOBAL_KEYWORDS.contains(token)) {
            return "Global Reserved Keyword (Prohibited everywhere)";
        }
        if (CONTEXTUAL_KEYWORDS.contains(token)) {
            return "Contextual Keyword (Legal as variable name, restricted in declarations)";
        }
        return "Standard Identifier";
    }

    public static void main(String[] args) {
        // Demonstrating that contextual keywords are valid variable names
        int var = 10;
        String record = "PatientRecord";
        System.out.println("Variable 'var' value: " + var);
        System.out.println("Variable 'record' value: " + record);
        System.out.println("var classification: " + inspectKeywordType("var"));
        System.out.println("class classification: " + inspectKeywordType("class"));
    }
}

