public class Solution {
    public static boolean containsConfusableGlyphs(String identifier) {
        for (int i = 0; i < identifier.length(); i++) {
            int cp = identifier.codePointAt(i);
            // Flag non-ASCII characters acting as confusable Latin lookalikes
            if (cp > 127) {
                Character.UnicodeScript script = Character.UnicodeScript.of(cp);
                if (script == Character.UnicodeScript.CYRILLIC || script == Character.UnicodeScript.GREEK) {
                    return true;
                }
            }
        }
        return false;
    }

    public static void main(String[] args) {
        String standardVar = "account";
        // 'а' in Cyrillic (U+0430) instead of ASCII 'a' (U+0061)
        String spoofedVar = "\u0430ccount";

        System.out.println("Testing '" + standardVar + "': homoglyph detected = " + containsConfusableGlyphs(standardVar));
        System.out.println("Testing '" + spoofedVar + "': homoglyph detected = " + containsConfusableGlyphs(spoofedVar));
    }
}

import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;

public class Solution {
    private static final Set<String> RESERVED = new HashSet<>(Arrays.asList(
        "class", "public", "static", "void", "int", "while", "for", "true", "false", "null", "_"
    ));

    public static String validateWithDiagnostics(String token) {
        if (token == null || token.isEmpty()) {
            return "INVALID: Token is null or empty";
        }
        if (RESERVED.contains(token)) {
            return "INVALID: Token matches reserved keyword or literal";
        }
        char first = token.charAt(0);
        if (Character.isDigit(first)) {
            return "INVALID: Cannot begin with numeric digit";
        }
        if (!Character.isJavaIdentifierStart(first)) {
            return "INVALID: Illegal start character '" + first + "'";
        }
        for (int i = 1; i < token.length(); i++) {
            char ch = token.charAt(i);
            if (Character.isWhitespace(ch)) {
                return "INVALID: Contains illegal whitespace at index " + i;
            }
            if (ch == '-') {
                return "INVALID: Contains illegal hyphen at index " + i;
            }
            if (!Character.isJavaIdentifierPart(ch)) {
                return "INVALID: Illegal character '" + ch + "' at index " + i;
            }
        }
        return "VALID";
    }

    public static void main(String[] args) {
        String[] candidates = {"3items", "user-name", "class", "total price", "validVar$"};
        for (String c : candidates) {
            System.out.println(c + " -> " + validateWithDiagnostics(c));
        }
    }
}

public class Solution {
    public static void convertAllCases(String phrase) {
        String[] tokens = phrase.trim().split("[\\s_-]+");
        for (int i = 0; i < tokens.length; i++) {
            tokens[i] = tokens[i].toLowerCase();
        }

        // PascalCase
        StringBuilder pascal = new StringBuilder();
        for (String t : tokens) {
            if (!t.isEmpty()) pascal.append(Character.toUpperCase(t.charAt(0))).append(t.substring(1));
        }

        // camelCase
        StringBuilder camel = new StringBuilder(tokens[0]);
        for (int i = 1; i < tokens.length; i++) {
            if (!tokens[i].isEmpty()) {
                camel.append(Character.toUpperCase(tokens[i].charAt(0))).append(tokens[i].substring(1));
            }
        }

        // snake_case, kebab-case, UPPER_SNAKE_CASE
        String snake = String.join("_", tokens);
        String kebab = String.join("-", tokens);
        String upperSnake = snake.toUpperCase();

        System.out.println("PascalCase: " + pascal);
        System.out.println("camelCase: " + camel);
        System.out.println("snake_case: " + snake);
        System.out.println("kebab-case: " + kebab);
        System.out.println("UPPER_SNAKE_CASE: " + upperSnake);
    }

