import java.util.Arrays;
import java.util.HashSet;
import java.util.Set;
import java.util.TreeSet;

public class Solution {
    private static final Set<String> KEYWORDS = new HashSet<>(Arrays.asList(
        "public", "class", "static", "void", "main", "int", "String", "return", "if", "new"
    ));

    public static Set<String> extractIdentifiers(String code) {
        // 1. Strip comments and string literals
        String clean = code.replaceAll("//.*", "")
                           .replaceAll("/\\*.*?\\*/", "")
                           .replaceAll("\"([^\\\"\\]|\\\\.)*\"", "");

        // 2. Tokenize by non-identifier characters
        String[] tokens = clean.split("[^a-zA-Z0-9_$]+");
        Set<String> identifiers = new TreeSet<>();
        for (String t : tokens) {
            if (!t.isEmpty() && !KEYWORDS.contains(t) && Character.isJavaIdentifierStart(t.charAt(0))) {
                identifiers.add(t);
            }
        }
        return identifiers;
    }

    public static void main(String[] args) {
        String snippet = "public class Demo {\n" +
                         "    // Comment with fakeVar\n" +
                         "    int score = 42;\n" +
                         "    String title = \"Sample text\";\n" +
                         "    void display() { int count = 10; }\n" +
                         "}";
        Set<String> result = extractIdentifiers(snippet);
        System.out.println("Extracted Identifiers: " + result);
    }
}

public class Solution {
    public static void lintSource(String[] lines) {
        for (int i = 0; i < lines.length; i++) {
            String line = lines[i].trim();
            int lineNum = i + 1;
            if (line.contains("static final")) {
                // Check for non-UPPER_SNAKE_CASE
                String[] parts = line.split("\\s+");
                for (int p = 0; p < parts.length; p++) {
                    if (parts[p].equals("final") && p + 2 < parts.length) {
                        String ident = parts[p + 2].replace(";", "").split("=")[0].trim();
                        if (!ident.matches("^[A-Z][A-Z0-9_]*$")) {
                            System.out.println("Line " + lineNum + ": Constant '" + ident + "' should be UPPER_SNAKE_CASE");
                        }
                    }
                }
            } else if (line.matches(".*\\b(int|String|double)\\s+([a-zA-Z0-9_]+).*")) {
                String ident = line.replaceAll(".*\\b(int|String|double)\\s+([a-zA-Z0-9_]+).*", "$2");
                if (!ident.matches("^[a-z][a-zA-Z0-9]*$")) {
                    System.out.println("Line " + lineNum + ": Variable '" + ident + "' should be lower camelCase");
                }
            }
        }
    }

    public static void main(String[] args) {
        String[] sourceCode = {
            "int user_age = 25;",
            "static final int maxItems = 100;",
            "String ValidName = \"John\";",
            "double balance = 50.0;"
        };
        lintSource(sourceCode);
    }
}

