import java.util.Set;

public class Solution {
    private static final Set<String> RESERVED = new HashSet<>(Arrays.asList(
        "class", "int", "void", "return", "if", "for", "static", "public"
    ));

    public static String safeRename(String code, String oldVar, String newVar) {
        if (RESERVED.contains(newVar) || !Character.isJavaIdentifierStart(newVar.charAt(0))) {
            throw new IllegalArgumentException("Rename rejected: '" + newVar + "' is a reserved word or illegal identifier.");
        }
        // Check collision
        if (code.matches(".*\\b" + newVar + "\\b.*")) {
            throw new IllegalStateException("Rename rejected: Variable '" + newVar + "' already exists in scope.");
        }
        return code.replaceAll("\\b" + oldVar + "\\b", newVar);
    }

    public static void main(String[] args) {
        String snippet = "int score = 10; score += 5; System.out.println(score);";
        System.out.println("Original: " + snippet);
        String refactored = safeRename(snippet, "score", "points");
        System.out.println("Refactored: " + refactored);
    }
}

public class Solution {
    public static void parseTokenContexts(String[] tokens) {
        for (int i = 0; i < tokens.length; i++) {
            String current = tokens[i];
            if (current.equals("class") && i + 1 < tokens.length) {
                System.out.println("Class Identifier: " + tokens[++i]);
            } else if ((current.equals("int") || current.equals("void") || current.equals("String")) && i + 1 < tokens.length) {
                String nextToken = tokens[i + 1];
                if (i + 2 < tokens.length && tokens[i + 2].equals("(")) {
                    System.out.println("Method Identifier: " + nextToken);
                    i += 2;
                } else if (i + 2 < tokens.length && (tokens[i + 2].equals("=") || tokens[i + 2].equals(";"))) {
                    System.out.println("Field Identifier: " + nextToken);
                    i += 1;
                }
            }
        }
    }

    public static void main(String[] args) {
        String[] tokens = {"public", "class", "OrderService", "{", "int", "orderCount", ";", "void", "processOrder", "(", ")", "}"};
        parseTokenContexts(tokens);
    }
}

import java.util.HashMap;
import java.util.Map;

public class Solution {
    public static void main(String[] args) {
        String originalSnippet = "int totalAmount = 100; int bonus = 20; int finalScore = totalAmount + bonus;";

        Map<String, String> obfuscationMap = new HashMap<>();
        obfuscationMap.put("totalAmount", "$_$");
        obfuscationMap.put("bonus", "$$");
        obfuscationMap.put("finalScore", "_$$");

        String obfuscated = originalSnippet;
        for (Map.Entry<String, String> entry : obfuscationMap.entrySet()) {
            obfuscated = obfuscated.replaceAll("\\b" + entry.getKey() + "\\b", entry.getValue());
        }

        System.out.println("Original Source:\n" + originalSnippet);
        System.out.println("Obfuscated Source:\n" + obfuscated);
        System.out.println("Verification: All generated symbols are legal Java identifiers.");
    }
}

